"use client";

import { Compass, Palette, Terminal } from "lucide-react";
import { CardStack, type CardStackItem } from "@/components/custom/blocks/CardStackBlock";

const ARRIVALS: CardStackItem[] = [
  {
    id: "maker-hunt",
    title: "MakerHunt",
    description: "Daily product launches for indie makers.",
    category: "Productivity",
    date: "1d ago",
    icon: <Compass className="size-6" />,
  },
  {
    id: "design-forge",
    title: "DesignForge",
    description: "AI-powered vector generation and canvas tools.",
    category: "Design",
    date: "2d ago",
    icon: <Palette className="size-6" />,
  },
  {
    id: "dev-pulse",
    title: "DevPulse",
    description: "Real-time deployment monitors and error alerts.",
    category: "Developer Tools",
    date: "3d ago",
    icon: <Terminal className="size-6" />,
  },
];

export default function ButtonStackDemo() {
  return (
    <CardStack
      items={ARRIVALS}
      swipeToDismiss={false}
      showNavigation={true}
      slideDirection="right"
    />
  );
}

"use client";

import React, { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import gsap from "gsap";
import { ArrowLeft, ArrowRight, ArrowUpRight, RotateCcw } from "lucide-react";
import { cn } from "@/lib/utils";
import { bezierEase, prefersReducedMotion } from "./gsap-motion";
import { springEase } from "./motion-curves";

export interface CardStackItem {
  id: string | number;
  title: string;
  description?: string;
  category?: string;
  date?: string;
  meta?: string;
  icon?: React.ReactNode | string;
  href?: string;
  [key: string]: unknown;
}

export interface CardStackProps extends React.HTMLAttributes<HTMLDivElement> {
  items: CardStackItem[];
  title?: string;
  /** Maximum number of cards visually stacked (front card + cards behind). Defaults to 3. */
  visibleCards?: number;
  /** Direction the card slides off on next: "right" | "left". Defaults to "right". */
  slideDirection?: "right" | "left";
  /** Whether the stack loops infinitely or stops at ends. Defaults to false. */
  loop?: boolean;
  /** Initial active card index. Defaults to 0. */
  defaultIndex?: number;
  /** Callback fired when the active card index changes. */
  onCardChange?: (index: number) => void;
  /** Callback fired when a card is dismissed/swiped. */
  onDismiss?: (item: CardStackItem, direction: "left" | "right") => void;
  /** Custom render function for card content. */
  renderCard?: (item: CardStackItem, index: number, isTop: boolean) => React.ReactNode;
  /** Custom class for individual cards. */
  cardClassName?: string;
  /** Enable dragging and swiping the top card to discard (left or right). Defaults to false. */
  swipeToDismiss?: boolean;
  /** Whether to show header navigation buttons (arrows). Defaults to true. Set to false for pure swipe-to-discard mode. */
  showNavigation?: boolean;
  /** Whether to render the header bar (title, counter, and navigation). Defaults to true. */
  showHeader?: boolean;
  /** Whether the last card can be dismissed in swipe mode. Defaults to false. */
  canDismissLastCard?: boolean;
}

// ============================================================================
// MOTION
// ============================================================================

/** Cards settle into their slot through this spring (position, tilt, fade). */
const SETTLE = springEase({ stiffness: 280, damping: 26, mass: 0.8 });
/** A card leaving the deck flies out over a fixed, fast-out curve. */
const EXIT = { duration: 0.26, ease: bezierEase([0.25, 1, 0.5, 1]) };

/** The card follows the pointer at 80% (an elastic pull against its slot). */
const DRAG_ELASTIC = 0.8;
/** Pointer travel before a press becomes a drag. */
const DRAG_START_PX = 3;
/** Release past this distance, or faster than this speed (px/s), to discard. */
const SWIPE_OFFSET = 80;
const SWIPE_VELOCITY = 280;
/** A drag released short of discarding springs back to the slot. */
const RETURN_SPRING = { stiffness: 200, damping: 40 };

/** Drag tilt: ±18° across ±260px of travel, clamped beyond. */
const dragTilt = (x: number) => Math.min(Math.max((x / 260) * 18, -18), 18);

interface CardPose {
  x: number;
  y: number;
  rotation: number;
  opacity: number;
  scale: number;
  zIndex: number;
}

/** Where a card rests at depth `offset` (0 is the front card). */
const restPose = (offset: number, count: number): CardPose => ({
  x: offset * 8,
  y: -offset * 4,
  rotation: offset * 1.6,
  opacity: 1,
  scale: 1,
  zIndex: count - offset,
});

/**
 * Where a card joining the deck starts: going back, the new front card swings
 * in from the slide side; any other newcomer fades in at its slot.
 */
const enterPose = (
  offset: number,
  count: number,
  direction: number,
  slideMultiplier: number,
): CardPose =>
  offset === 0 && direction < 0
    ? {
        x: 220 * slideMultiplier,
        y: -10,
        rotation: 8 * slideMultiplier,
        opacity: 0,
        scale: 0.98,
        zIndex: count + 2,
      }
    : { ...restPose(offset, count), opacity: 0 };

/** The first-paint style for a pose, so server HTML already shows the fan. */
const poseStyle = (pose: CardPose): React.CSSProperties => ({
  transform: `translate(${pose.x}px, ${pose.y}px) rotate(${pose.rotation}deg) scale(${pose.scale})`,
  opacity: pose.opacity,
  zIndex: pose.zIndex,
});

/** Pointer speed (px/s) over the last 100ms of samples. */
function releaseVelocity(history: { x: number; t: number }[]) {
  if (history.length < 2) return 0;
  const last = history[history.length - 1];
  let sample = history[0];
  for (let i = history.length - 1; i >= 0; i--) {
    sample = history[i];
    if (last.t - sample.t > 100) break;
  }
  const seconds = (last.t - sample.t) / 1000;
  return seconds === 0 ? 0 : (last.x - sample.x) / seconds;
}

// ============================================================================
// CARD
// ============================================================================

interface StackCardItemProps {
  item: CardStackItem;
  offset: number;
  isTop: boolean;
  count: number;
  /** The pose this card mounts in; read once, on mount. */
  start: CardPose;
  /** Set once the card has left the deck: it flies out, then unmounts. */
  exit: { x: number; rotation: number } | null;
  isDraggable: boolean;
  onSwipe: (dir: "left" | "right") => void;
  onExited: (id: CardStackItem["id"]) => void;
  renderCard?: (item: CardStackItem, index: number, isTop: boolean) => React.ReactNode;
  cardClassName?: string;
}

function StackCardItem({
  item,
  offset,
  isTop,
  count,
  start,
  exit,
  isDraggable,
  onSwipe,
  onExited,
  renderCard,
  cardClassName,
}: StackCardItemProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [startPose] = useState(start);
  const [startStyle] = useState(() => poseStyle(start));
  /** Horizontal drag offset, for telling a drag from a click on the link. */
  const dragX = useRef(0);
  const endDrag = useRef<(() => void) | null>(null);
  const latestSwipe = useRef(onSwipe);

  useLayoutEffect(() => {
    latestSwipe.current = onSwipe;
  });

  const rest = restPose(offset, count);
  const { x, y, rotation, zIndex } = rest;
  const exiting = exit !== null;
  const exitX = exit?.x ?? 0;
  const exitRotation = exit?.rotation ?? 0;
  const id = item.id;

  // Mount: place the card in its starting pose before the first paint.
  useLayoutEffect(() => {
    if (ref.current) gsap.set(ref.current, startPose);
  }, [startPose]);

  // Settle into the slot, or fly out once the card has left the deck.
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const reduce = prefersReducedMotion();

    if (exiting) {
      endDrag.current?.();
      const target = { x: exitX, y: -10, rotation: exitRotation, opacity: 0, scale: 0.96, zIndex: count + 2 };
      if (reduce) {
        gsap.set(el, target);
        onExited(id);
        return;
      }
      const tween = gsap.to(el, {
        ...target,
        duration: EXIT.duration,
        ease: EXIT.ease,
        overwrite: "auto",
        onComplete: () => onExited(id),
      });
      return () => {
        tween.kill();
      };
    }

    const target = { x, y, rotation, opacity: 1, scale: 1, zIndex };
    if (reduce) {
      gsap.set(el, target);
      return;
    }
    const tween = gsap.to(el, {
      ...target,
      duration: SETTLE.duration,
      ease: SETTLE.ease,
      overwrite: "auto",
    });
    return () => {
      tween.kill();
    };
  }, [x, y, rotation, zIndex, exiting, exitX, exitRotation, count, id, onExited]);

  // Unmount: drop any drag in progress and the drag's return spring.
  useEffect(() => {
    const el = ref.current;
    return () => {
      endDrag.current?.();
      if (el) gsap.killTweensOf(el);
    };
  }, []);

  const paintDrag = (el: HTMLElement, value: number) => {
    dragX.current = value;
    gsap.set(el, { x: value, rotation: dragTilt(value) });
  };

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    const el = ref.current;
    if (!el || !isDraggable || exiting) return;
    if (e.pointerType === "mouse" ? e.button !== 0 : e.isPrimary === false) return;
    endDrag.current?.();

    const pointerId = e.pointerId;
    const startX = e.pageX;
    const startY = e.pageY;
    const origin = Number(gsap.getProperty(el, "x")) || 0;
    const history = [{ x: e.pageX, t: performance.now() }];
    let lastX = e.pageX;
    let dragging = false;

    const move = (ev: PointerEvent) => {
      if (ev.pointerId !== pointerId) return;
      lastX = ev.pageX;
      history.push({ x: ev.pageX, t: performance.now() });
      const dx = ev.pageX - startX;
      if (!dragging) {
        if (Math.hypot(dx, ev.pageY - startY) < DRAG_START_PX) return;
        dragging = true;
        gsap.killTweensOf(el, "x,rotation");
      }
      paintDrag(el, (origin + dx) * DRAG_ELASTIC);
    };

    const stop = () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", end);
      window.removeEventListener("pointercancel", end);
      endDrag.current = null;
    };

    const end = (ev: PointerEvent) => {
      if (ev.pointerId !== pointerId) return;
      stop();
      if (!dragging) return;
      const offsetX = (ev.type === "pointercancel" ? lastX : ev.pageX) - startX;
      const velocity = releaseVelocity(history);
      if (offsetX > SWIPE_OFFSET || velocity > SWIPE_VELOCITY) {
        latestSwipe.current("right");
      } else if (offsetX < -SWIPE_OFFSET || velocity < -SWIPE_VELOCITY) {
        latestSwipe.current("left");
      } else {
        const from = dragX.current;
        if (from === 0) return;
        if (prefersReducedMotion()) {
          paintDrag(el, 0);
          return;
        }
        const { duration, ease } = springEase({
          ...RETURN_SPRING,
          restDelta: Math.min(1, 1 / Math.abs(from)),
        });
        gsap.to(el, {
          x: 0,
          duration,
          ease,
          overwrite: "auto",
          onUpdate: () => paintDrag(el, Number(gsap.getProperty(el, "x")) || 0),
        });
      }
    };

    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", end);
    window.addEventListener("pointercancel", end);
    endDrag.current = stop;
  };

  return (
    <div
      ref={ref}
      onPointerDown={handlePointerDown}
      style={{ transformOrigin: "bottom center", ...startStyle }}
      className={cn(
        "absolute inset-x-0 bottom-0 top-0 rounded-[26px] border border-foreground/10 dark:border-foreground/15 bg-card p-6 shadow-[0_10px_25px_-5px_rgba(0,0,0,0.06),0_2px_6px_-2px_rgba(0,0,0,0.04)] dark:shadow-[0_12px_28px_-6px_rgba(0,0,0,0.6),0_2px_6px_-2px_rgba(0,0,0,0.4)] flex flex-col justify-between overflow-hidden",
        isDraggable
          ? "cursor-grab active:cursor-grabbing touch-none select-none"
          : isTop
          ? "cursor-default select-none"
          : "pointer-events-none select-none",
        cardClassName,
      )}
    >
      {renderCard ? (
        renderCard(item, offset, isTop)
      ) : (
        <>
          {/* Card Header: Icon, Title, and Action Link */}
          <div className="flex items-start justify-between gap-3">
            <div className="flex items-center gap-3.5 min-w-0">
              {item.icon && (
                <div className="size-12 shrink-0 rounded-2xl overflow-hidden flex items-center justify-center pointer-events-none">
                  {typeof item.icon === "string" ? (
                    <img
                      src={item.icon}
                      alt={item.title}
                      className="size-full object-cover"
                    />
                  ) : (
                    item.icon
                  )}
                </div>
              )}
              <h3 className="font-bold text-xl text-foreground tracking-tight truncate pointer-events-none">
                {item.title}
              </h3>
            </div>
            {item.href && (
              <a
                href={item.href}
                target="_blank"
                rel="noreferrer"
                aria-label={`Open ${item.title}`}
                onClick={(e) => {
                  // Prevent navigation if user was dragging
                  if (Math.abs(dragX.current) > 5) {
                    e.preventDefault();
                  }
                }}
                className="text-foreground hover:text-primary transition-colors p-0.5 shrink-0 z-20"
              >
                <ArrowUpRight className="size-6 stroke-[2.2]" />
              </a>
            )}
          </div>

          {/* Description */}
          {item.description && (
            <p className="mt-3 text-[15px] text-muted-foreground line-clamp-2 leading-relaxed font-normal pointer-events-none">
              {item.description}
            </p>
          )}

          {/* Footer Meta */}
          {(item.category || item.date || item.meta) && (
            <div className="mt-4 flex items-center gap-2 text-xs font-medium text-muted-foreground/80 pointer-events-none">
              {item.category && <span>{item.category}</span>}
              {item.category && (item.date || item.meta) && (
                <span>·</span>
              )}
              {item.date && <span>{item.date}</span>}
              {!item.date && item.meta && <span>{item.meta}</span>}
            </div>
          )}
        </>
      )}
    </div>
  );
}

// ============================================================================
// DECK (keeps leaving cards mounted until they have flown out)
// ============================================================================

interface DeckEntry {
  item: CardStackItem;
  offset: number;
}

interface ExitingCard extends DeckEntry {
  exit: { x: number; rotation: number };
}

const sameDeck = (a: DeckEntry[], b: DeckEntry[]) =>
  a.length === b.length &&
  a.every((entry, i) => entry.item.id === b[i].item.id && entry.offset === b[i].offset);

interface CardDeckProps {
  visible: DeckEntry[];
  count: number;
  direction: 1 | -1;
  slideMultiplier: number;
  swipeToDismiss: boolean;
  canDismiss: boolean;
  onSwipe: (dir: "left" | "right") => void;
  renderCard?: (item: CardStackItem, index: number, isTop: boolean) => React.ReactNode;
  cardClassName?: string;
}

function CardDeck({
  visible,
  count,
  direction,
  slideMultiplier,
  swipeToDismiss,
  canDismiss,
  onSwipe,
  renderCard,
  cardClassName,
}: CardDeckProps) {
  const [shown, setShown] = useState(visible);
  const [exiting, setExiting] = useState<ExitingCard[]>([]);
  // The cards on screen when the deck mounts appear in place; any card that
  // joins later animates in.
  const [animateEntries, setAnimateEntries] = useState(false);

  if (!sameDeck(shown, visible)) {
    const ids = new Set(visible.map((entry) => entry.item.id));
    const left = shown.filter((entry) => !ids.has(entry.item.id));
    const flyX = 320 * (swipeToDismiss ? 1 : slideMultiplier);
    const flyRotation = 14 * (swipeToDismiss ? 1 : slideMultiplier);
    setExiting((prev) => [
      // A card that comes back mid-flight rejoins the deck from where it is.
      ...prev.filter((entry) => !ids.has(entry.item.id)),
      ...left.map((entry) => ({
        ...entry,
        exit: {
          x: direction > 0 ? flyX : -flyX,
          rotation: direction > 0 ? flyRotation : -flyRotation,
        },
      })),
    ]);
    setShown(visible);
    setAnimateEntries(true);
  }

  const handleExited = useCallback((id: CardStackItem["id"]) => {
    setExiting((prev) => prev.filter((entry) => entry.item.id !== id));
  }, []);

  const entries = [
    ...exiting.filter((entry) => !visible.some((v) => v.item.id === entry.item.id)),
    ...visible
      .slice()
      .reverse()
      .map((entry) => ({ ...entry, exit: null })),
  ];

  return (
    <>
      {entries.map(({ item, offset, exit }) => {
        const isTop = offset === 0;
        return (
          <StackCardItem
            key={item.id}
            item={item}
            offset={offset}
            isTop={isTop}
            count={count}
            start={
              animateEntries
                ? enterPose(offset, count, direction, slideMultiplier)
                : restPose(offset, count)
            }
            exit={exit}
            isDraggable={isTop && swipeToDismiss && canDismiss}
            onSwipe={onSwipe}
            onExited={handleExited}
            renderCard={renderCard}
            cardClassName={cardClassName}
          />
        );
      })}
    </>
  );
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const CardStack = React.forwardRef<HTMLDivElement, CardStackProps>(
  (
    {
      items,
      title,
      visibleCards = 3,
      slideDirection = "right",
      loop = false,
      defaultIndex = 0,
      onCardChange,
      onDismiss,
      renderCard,
      className,
      cardClassName,
      swipeToDismiss = false,
      showNavigation = true,
      showHeader = true,
      canDismissLastCard = false,
      ...props
    },
    ref,
  ) => {
    const [currentIndex, setCurrentIndex] = useState(
      Math.min(Math.max(0, defaultIndex), Math.max(0, items.length - 1)),
    );
    const [direction, setDirection] = useState<1 | -1>(1);

    if (!items || items.length === 0) {
      return null;
    }

    const total = items.length;
    const isCompleted = currentIndex >= total;
    const canPrev = loop ? true : currentIndex > 0;
    const canNext = loop ? true : currentIndex < total - 1;
    const canDismiss = loop || canDismissLastCard || currentIndex < total - 1;

    const handlePrev = () => {
      if (!canPrev) return;
      setDirection(-1);
      const nextIdx = currentIndex > 0 ? currentIndex - 1 : total - 1;
      setCurrentIndex(nextIdx);
      onCardChange?.(nextIdx);
    };

    const handleNext = () => {
      if (!canNext) return;
      setDirection(1);
      const nextIdx = currentIndex < total - 1 ? currentIndex + 1 : 0;
      setCurrentIndex(nextIdx);
      onCardChange?.(nextIdx);
    };

    const handleDismissCard = (dismissDir: "left" | "right") => {
      if (!canDismiss) return;
      const currentItem = items[currentIndex % total];
      setDirection(dismissDir === "right" ? 1 : -1);
      const nextIdx = loop ? (currentIndex + 1) % total : currentIndex + 1;
      setCurrentIndex(nextIdx);
      onDismiss?.(currentItem, dismissDir);
      onCardChange?.(nextIdx % total);
    };

    // Calculate visible cards from current index
    const visibleItems: DeckEntry[] = [];
    const count = Math.min(visibleCards, total);

    if (!isCompleted) {
      for (let i = 0; i < count; i++) {
        const itemIndex = (currentIndex + i) % total;
        if (!loop && currentIndex + i >= total) {
          break;
        }
        visibleItems.push({
          item: items[itemIndex],
          offset: i,
        });
      }
    }

    const slideMultiplier = slideDirection === "left" ? -1 : 1;

    return (
      <div
        ref={ref}
        className={cn("w-full max-w-[500px] select-none", className)}
        {...props}
      >
        {/* Header: Title/Counter on left, Navigation Arrows on right */}
        {showHeader && (
          <div className="flex items-center justify-between mb-4 px-1">
            {title ? (
              <h2 className="text-xl font-bold tracking-tight text-foreground">
                {title}
              </h2>
            ) : (
              <span className="text-sm font-medium text-muted-foreground/80 tabular-nums">
                {isCompleted ? "0 left" : `${Math.min(currentIndex + 1, total)} of ${total}`}
              </span>
            )}
            <div className="flex items-center gap-3">
              {title && (
                <span className="text-sm font-medium text-muted-foreground/80 tabular-nums">
                  {isCompleted ? "0 left" : `${Math.min(currentIndex + 1, total)} of ${total}`}
                </span>
              )}
              {showNavigation && (
                <div className="flex items-center gap-1.5">
                  <button
                    type="button"
                    onClick={handlePrev}
                    disabled={!canPrev}
                    aria-label="Previous card"
                    className="size-9 rounded-xl border border-foreground/10 dark:border-foreground/15 bg-card hover:bg-muted active:scale-95 transition-all flex items-center justify-center text-foreground disabled:opacity-30 disabled:pointer-events-none shadow-xs"
                  >
                    <ArrowLeft className="size-4" />
                  </button>
                  <button
                    type="button"
                    onClick={handleNext}
                    disabled={!canNext}
                    aria-label="Next card"
                    className="size-9 rounded-xl border border-foreground/10 dark:border-foreground/15 bg-card hover:bg-muted active:scale-95 transition-all flex items-center justify-center text-foreground disabled:opacity-30 disabled:pointer-events-none shadow-xs"
                  >
                    <ArrowRight className="size-4" />
                  </button>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Stack Container with generous padding so stacked cards and shadows never clip */}
        <div className="relative w-full overflow-hidden pt-7 pr-12 pb-8 pl-2">
          <div className="relative h-[195px] sm:h-[200px] w-full">
            {isCompleted ? (
              <div className="size-full rounded-[26px] border border-dashed border-foreground/15 dark:border-foreground/20 flex flex-col items-center justify-center gap-3 p-6 text-center bg-muted/20">
                <p className="text-sm font-medium text-muted-foreground">
                  All cards have been reviewed!
                </p>
                <button
                  type="button"
                  onClick={() => setCurrentIndex(0)}
                  className="inline-flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-semibold bg-primary text-primary-foreground hover:opacity-90 active:scale-95 transition-all shadow-xs"
                >
                  <RotateCcw className="size-3.5" />
                  Replay deck
                </button>
              </div>
            ) : (
              <CardDeck
                visible={visibleItems}
                count={count}
                direction={direction}
                slideMultiplier={slideMultiplier}
                swipeToDismiss={swipeToDismiss}
                canDismiss={canDismiss}
                onSwipe={handleDismissCard}
                renderCard={renderCard}
                cardClassName={cardClassName}
              />
            )}
          </div>
        </div>
      </div>
    );
  },
);

CardStack.displayName = "CardStack";

export default CardStack;

import gsap from "gsap";
import { cubicBezier, type FrameTicker } from "./motion-curves";

/**
 * GSAP-side glue for the GSAP builds of components that also ship a Motion
 * Motion twin. Kept apart from motion-curves.ts so the library-free curves
 * never pull GSAP into a CSS or Motion build.
 */

/** `gsap.ticker` as a FrameTicker, so spring followers run on GSAP's loop. */
export const gsapTicker: FrameTicker = {
  add(callback) {
    const tick = (_time: number, deltaTime: number) => callback(deltaTime);
    gsap.ticker.add(tick);
    return () => gsap.ticker.remove(tick);
  },
};

/** A Motion / CSS cubic-bezier array as a GSAP ease. */
export const bezierEase = (curve: readonly [number, number, number, number] | readonly number[]) =>
  cubicBezier(curve[0], curve[1], curve[2], curve[3]);

/** `(prefers-reduced-motion: reduce)` right now. */
export const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;

/**
 * Motion curves with no animation library behind them.
 *
 * The components here ship as CSS, GSAP or Motion builds that must move
 * identically, so the curves are computed once, from the same numbers, and
 * handed to whichever engine runs them:
 *
 *   - `cubicBezier(x1, y1, x2, y2)` → an easing function (GSAP accepts any
 *     `(progress) => value` as `ease`), exact for Motion's `ease: [..]` arrays
 *     and for CSS `cubic-bezier()`.
 *   - `spring({ stiffness, damping, mass })` → the analytic solution Motion
 *     Motion uses, as an easing function plus the time it takes to settle, or
 *     as a CSS `linear()` string for a fixed start and end.
 *   - `createSpringFollower` → a value that chases a moving target through the
 *     same spring every frame, like Motion's `useSpring`, for pointer-driven
 *     motion that no fixed curve can describe.
 */

// ---------------------------------------------------------------------------
// Cubic bezier
// ---------------------------------------------------------------------------

/**
 * The CSS / Motion cubic-bezier as a function of progress. Newton-Raphson
 * with a bisection fallback, the same solver browsers use.
 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  if (x1 === y1 && x2 === y2) return (t: number) => t;

  const a = (p1: number, p2: number) => 1 - 3 * p2 + 3 * p1;
  const b = (p1: number, p2: number) => 3 * p2 - 6 * p1;
  const c = (p1: number) => 3 * p1;
  const at = (t: number, p1: number, p2: number) =>
    ((a(p1, p2) * t + b(p1, p2)) * t + c(p1)) * t;
  const slope = (t: number, p1: number, p2: number) =>
    3 * a(p1, p2) * t * t + 2 * b(p1, p2) * t + c(p1);

  const solveX = (x: number) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const s = slope(t, x1, x2);
      if (Math.abs(s) < 1e-6) break;
      const err = at(t, x1, x2) - x;
      if (Math.abs(err) < 1e-7) return t;
      t -= err / s;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 30 && hi - lo > 1e-7; i++) {
      const value = at(t, x1, x2);
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return t;
  };

  return (x: number) => (x <= 0 ? 0 : x >= 1 ? 1 : at(solveX(x), y1, y2));
}

/** Motion's named eases, as the cubic-beziers they are. */
export const MOTION_EASE = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
  circIn: [0.55, 0, 1, 0.45],
  circOut: [0.55, 0, 0.45, 1],
  circInOut: [0.85, 0, 0.15, 1],
  backIn: [0.31, 0.01, 0.66, -0.59],
  backOut: [0.33, 1.53, 0.69, 0.99],
  anticipate: [0.66, -0.56, 0.34, 1.35],
} as const;

/**
 * Motion's default layout transition (`layout` / `layoutId`):
 * `{ duration: 0.45, ease: [0.4, 0, 0.1, 1] }`.
 */
export const LAYOUT_TRANSITION = { duration: 0.45, ease: [0.4, 0, 0.1, 1] as const };

// ---------------------------------------------------------------------------
// Spring
// ---------------------------------------------------------------------------

export interface SpringOptions {
  /** Motion default 100. */
  stiffness?: number;
  /** Motion default 10. */
  damping?: number;
  /** Motion default 1. */
  mass?: number;
  /** Starting velocity, in units of the whole distance per second. */
  velocity?: number;
  /** How close to the end counts as settled, as a fraction of the distance. */
  restDelta?: number;
}

/**
 * Normalised position (0 → 1) of a spring released from 0 towards 1, at time
 * `t` seconds. The closed-form solution Motion's `spring()` generator
 * uses for the under-, critically and over-damped cases.
 */
export function springAt(options: SpringOptions = {}) {
  const { stiffness = 100, damping = 10, mass = 1, velocity = 0 } = options;
  const zeta = damping / (2 * Math.sqrt(stiffness * mass));
  const omega0 = Math.sqrt(stiffness / mass);
  // Motion's convention: distance still to cover, velocity toward it negated.
  const delta = 1;
  const v0 = -velocity;

  if (zeta < 1) {
    const omegaD = omega0 * Math.sqrt(1 - zeta * zeta);
    return (t: number) => {
      const envelope = Math.exp(-zeta * omega0 * t);
      return (
        1 -
        envelope *
          (((v0 + zeta * omega0 * delta) / omegaD) * Math.sin(omegaD * t) +
            delta * Math.cos(omegaD * t))
      );
    };
  }
  if (zeta === 1) {
    return (t: number) => 1 - Math.exp(-omega0 * t) * (delta + (v0 + omega0 * delta) * t);
  }
  const omegaD = omega0 * Math.sqrt(zeta * zeta - 1);
  return (t: number) => {
    const envelope = Math.exp(-zeta * omega0 * t);
    const freq = Math.min(omegaD * t, 300);
    return (
      1 -
      (envelope *
        ((v0 + zeta * omega0 * delta) * Math.sinh(freq) + omegaD * delta * Math.cosh(freq))) /
        omegaD
    );
  };
}

/** Seconds until the spring stays within `restDelta` of its end. */
export function springDuration(options: SpringOptions = {}) {
  const at = springAt(options);
  const restDelta = options.restDelta ?? 0.001;
  const step = 1 / 240;
  let lastOutside = 0;
  for (let t = 0; t <= 10; t += step) {
    if (Math.abs(1 - at(t)) > restDelta) lastOutside = t;
    else if (t - lastOutside > 0.1) break;
  }
  return Math.max(lastOutside + step, step);
}

/**
 * A spring as a duration and an easing function over it — what GSAP takes:
 *
 *   const { duration, ease } = springEase({ stiffness: 300, damping: 20 });
 *   gsap.to(el, { y: 0, duration, ease });
 *
 * Exact for a fixed start and end; a spring that has to react mid-flight to a
 * new target needs `createSpringFollower` instead.
 */
export function springEase(options: SpringOptions = {}) {
  const duration = springDuration(options);
  const at = springAt(options);
  return {
    duration,
    ease: (progress: number) => (progress >= 1 ? 1 : at(progress * duration)),
  };
}

/**
 * A spring as a CSS `linear()` easing and its duration in ms, for
 * `transition` / `animation` with a fixed start and end.
 *
 *   const { easing, duration } = springLinear({ stiffness: 400, damping: 30 });
 *   el.style.transition = `transform ${duration}ms ${easing}`;
 */
export function springLinear(options: SpringOptions = {}, pointsPerSecond = 60) {
  const duration = springDuration(options);
  const at = springAt(options);
  const count = Math.max(Math.ceil(duration * pointsPerSecond), 8);
  const points: string[] = [];
  for (let i = 0; i <= count; i++) {
    const t = (i / count) * duration;
    points.push(String(Math.round((i === count ? 1 : at(t)) * 10000) / 10000));
  }
  return { easing: `linear(${points.join(", ")})`, duration: Math.round(duration * 1000) };
}

// ---------------------------------------------------------------------------
// Spring follower (useSpring equivalent)
// ---------------------------------------------------------------------------

/** Something that calls back once per frame with the time since the last, in ms. */
export interface FrameTicker {
  add: (callback: (deltaMs: number) => void) => () => void;
}

/** requestAnimationFrame as a ticker — the library-free default. */
export const rafTicker: FrameTicker = {
  add(callback) {
    let last = performance.now();
    let frame = requestAnimationFrame(function tick(now) {
      callback(now - last);
      last = now;
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
  },
};

export interface SpringFollower {
  /** Chase a new target from wherever the value is now, keeping its velocity. */
  set: (target: number) => void;
  /** Move to a value instantly, with no motion. */
  jump: (value: number) => void;
  get: () => number;
  destroy: () => void;
}

/**
 * A value that follows its target through a spring, integrating the same
 * equation of motion Motion's `useSpring` solves — so a pointer-driven spring
 * reads the same in every build. Runs only while moving; `onUpdate` receives
 * each new value.
 */
export function createSpringFollower(
  initial: number,
  onUpdate: (value: number) => void,
  options: SpringOptions & { restSpeed?: number; ticker?: FrameTicker } = {},
): SpringFollower {
  const { stiffness = 100, damping = 10, mass = 1, ticker = rafTicker } = options;
  const restDelta = options.restDelta ?? 0.01;
  const restSpeed = options.restSpeed ?? 0.01;
  let value = initial;
  let target = initial;
  let velocity = 0;
  let stop: (() => void) | null = null;

  const step = (deltaMs: number) => {
    // Fixed 1ms sub-steps keep the integration stable for stiff springs and
    // independent of the frame rate.
    const steps = Math.min(Math.max(Math.round(deltaMs), 1), 250);
    for (let i = 0; i < steps; i++) {
      const force = -stiffness * (value - target) - damping * velocity;
      velocity += (force / mass) * 0.001;
      value += velocity * 0.001;
    }
    if (Math.abs(target - value) < restDelta && Math.abs(velocity) < restSpeed) {
      value = target;
      velocity = 0;
      stop?.();
      stop = null;
    }
    onUpdate(value);
  };

  return {
    set(next) {
      target = next;
      if (!stop && value !== target) stop = ticker.add(step);
    },
    jump(next) {
      stop?.();
      stop = null;
      value = target = next;
      velocity = 0;
      onUpdate(value);
    },
    get: () => value,
    destroy() {
      stop?.();
      stop = null;
    },
  };
}
